"""Apply frozen continuation and overheat gates to attention event paths."""
from __future__ import annotations
import argparse,json
from pathlib import Path
import numpy as np,pandas as pd
def bootstrap(values,seed=20260830,reps=20000):
 rng=np.random.default_rng(seed);return np.quantile([rng.choice(values,len(values),replace=True).mean() for _ in range(reps)],[.025,.975]).tolist()
def summarize(path):
 x=pd.read_csv(path);x=x[(x.observed_days>=35)&x.return_d35.notna()&x.active_d35.notna()].copy();x["year"]=pd.to_datetime(x.signal_date).dt.year;values=x.active_d35.to_numpy();interval=bootstrap(values) if len(values) else [np.nan,np.nan];cut=max(1,int(np.ceil(len(x)*.05))) if len(x) else 0;without_best=x.sort_values("active_d35").iloc[:-cut].active_d35.mean() if len(x)>cut else np.nan;without_worst=x.sort_values("active_d35").iloc[cut:].active_d35.mean() if len(x)>cut else np.nan;periods={str(year):{"count":len(g),"mean_active35":float(g.active_d35.mean()),"median_active35":float(g.active_d35.median())} for year,g in x.groupby("year")};medians={str(h):float(x[f"active_d{h}"].median()) for h in [30,35,40]};continuation={"count":len(x)>=30,"validation_count":len(x[x.year.eq(2025)])>=10,"holdout_count":len(x[x.year.eq(2026)])>=10,"absolute":float((x.return_d35>0).mean())>=.60,"outperform":float((x.active_d35>0).mean())>=.60,"success":float(((x.return_d35>0)&(x.active_d35>0)).mean())>=.55,"horizons":all(v>0 for v in medians.values()),"bootstrap":interval[0]>0,"trim":pd.notna(without_best) and without_best>0,"periods":all(periods.get(str(y),{}).get("mean_active35",0)>0 for y in [2024,2025,2026])};overheat={"count":len(x)>=30,"validation_count":len(x[x.year.eq(2025)])>=10,"holdout_count":len(x[x.year.eq(2026)])>=10,"absolute":float((x.return_d35<0).mean())>=.60,"underperform":float((x.active_d35<0).mean())>=.60,"success":float(((x.return_d35<0)&(x.active_d35<0)).mean())>=.55,"horizons":all(v<0 for v in medians.values()),"bootstrap":interval[1]<0,"trim":pd.notna(without_worst) and without_worst<0,"periods":all(periods.get(str(y),{}).get("mean_active35",0)<0 for y in [2024,2025,2026])};return {"complete35":len(x),"absolute_positive_rate":float((x.return_d35>0).mean()),"absolute_negative_rate":float((x.return_d35<0).mean()),"outperform_rate":float((x.active_d35>0).mean()),"underperform_rate":float((x.active_d35<0).mean()),"continuation_success_rate":float(((x.return_d35>0)&(x.active_d35>0)).mean()),"overheat_success_rate":float(((x.return_d35<0)&(x.active_d35<0)).mean()),"mean_active35":float(x.active_d35.mean()),"median_active":medians,"bootstrap95":interval,"trim_without_best5_mean":float(without_best),"trim_without_worst5_mean":float(without_worst),"periods":periods,"continuation_checks":continuation,"overheat_checks":overheat,"verdict":"GO-CONTINUATION" if all(continuation.values()) else "GO-OVERHEAT" if all(overheat.values()) else "NO-GO"}
def encode(value):return value.item() if hasattr(value,"item") else str(value)
def run(stock_path,etf_path,out_path):
 result={"stock":summarize(stock_path),"etf":summarize(etf_path)};Path(out_path).write_text(json.dumps(result,ensure_ascii=False,indent=2,default=encode)+"\n");return result
def main(argv=None):
 p=argparse.ArgumentParser();p.add_argument("--stock",default="overall/a-share-attention-stock-events.csv");p.add_argument("--etf",default="overall/a-share-attention-etf-events.csv");p.add_argument("--out",default="overall/a-share-attention-result.json");a=p.parse_args(argv);print(json.dumps(run(a.stock,a.etf,a.out),ensure_ascii=False,indent=2,default=encode));return 0
if __name__=="__main__":raise SystemExit(main())
